import { brandWhereOp } from "../../reads/where-ops.js";
import { isCountOp, where as viewWhere } from "../../reads/views.js";
import { normalizeWhere } from "./conditions.js";
import { assertReactionNodes } from "./nodes.js";
import { siblingTree } from "./partitions.js";
import { isChannelPattern } from "./channels.js";
import { actionPattern, branchChain } from "./nodes.js";
export { actionPattern } from "./nodes.js";
/** Read matching occurrences strictly before a trigger in its causal flow. */
export function earlier(action, input, output) {
    return brandWhereOp({
        op: "earlier",
        pattern: { ...actionPattern(action, input, output ?? {}), output: output ?? {} },
    });
}
/** Bind a fresh variable to the instant stamped on this causal flow's outermost occurrence. */
export function now(variable) {
    if (typeof variable !== "symbol") {
        throw new Error("now(variable) binds one logic variable to the current flow's instant.");
    }
    return brandWhereOp({ op: "now", out: variable });
}
export function when(line) {
    if (isChannelPattern(line))
        return createWhenBuilderFromPatterns([line]);
    if (typeof line !== "object" || line === null || line.kind !== "step") {
        throw new Error("when(...) takes one callable action line or posture channel.");
    }
    const pattern = {
        ...line.action,
        posture: line.linePosture ?? "requested",
        output: line.action.output ?? {},
    };
    return createWhenBuilderFromPatterns([pattern]);
}
function createWhenBuilderFromPatterns(patterns, stage = {}) {
    const builder = {
        where(...args) {
            const normalized = normalizeWhere(args, "when(...).where");
            if (normalized.fn !== undefined) {
                const functional = {
                    then(...nodes) {
                        assertReactionNodes(nodes);
                        return siblingTree(patterns, { where: normalized.fn }, nodes, stage);
                    },
                };
                return functional;
            }
            return declarativeWhenBuilder(patterns, normalized.ops, stage);
        },
        then(...nodes) {
            assertReactionNodes(nodes);
            return siblingTree(patterns, {}, nodes, stage);
        },
    };
    if (stage.deferred !== true) {
        builder.afterFlowSettles = () => createWhenBuilderFromPatterns(patterns, { deferred: true });
    }
    return builder;
}
function declarativeWhenBuilder(patterns, whereOps, stage) {
    return {
        then(...nodes) {
            assertReactionNodes(nodes);
            return siblingTree(patterns, { whereOps }, nodes, stage);
        },
    };
}
/** State a read conjunction, optionally qualifying one reaction branch with it. */
export function where(...conditions) {
    const block = viewWhere(...conditions);
    Object.defineProperty(block, "then", {
        value: (...nodes) => {
            if (nodes.length !== 1) {
                throw new Error("a branch-local then(...) takes one callable action line.");
            }
            if (block.some(isCountOp)) {
                throw new Error("count(...) cannot be used in a reaction condition. " +
                    "To return a row count, use each(line).count() in a former. " +
                    "To test a count as policy, define a view and read that view.");
            }
            return branchChain(block, nodes[0]);
        },
    });
    return block;
}
